      "cumple": true,
      "evidencia": "‘mono­lito modular con arquitectura en capas … una única aplicación FastAPI’"
    },
    {
      "id": "R2",
      "cumple": true,
      "evidencia": "‘Acceso a PostgreSQL: operaciones CRUD sobre la tabla wishlist_items’ y ‘única base de datos PostgreSQL’"
    },
    {
      "id": "R3",
      "cumple": true,
      "evidencia": "‘La comunicación es síncrona e in‑proceso entre capas’ y ‘evita colas o brokers externos’"
    },
    {
      "id": "R4",
      "cumple": true,
      "evidencia": "‘Email Notification Wrapper encapsula la llamada al servicio interno de correo (POST /internal/mail/send)’"
    },
    {
      "id": "R5",
      "cumple": true,
      "evidencia": "‘Price Detection Scheduler … tarea programada (cada hora) que recorre todas las wishlist’"
    },
    {
      "id": "R6",
      "cumple": true,
      "evidencia": "‘Todos los servicios usados (catálogo, correo interno, configuración) ya existen en la tienda; no se añaden nuevos externos’"
    }
  ],
  "specs": [
    {
      "id": "SPEC-01",
      "cubierto": true,
      "evidencia": "‘add_item’ en ARCH‑02 valida duplicados, límite 50 y guarda precio guardado; endpoint POST /wishlist/add devuelve mensajes"
    },
    {
      "id": "SPEC-02",
      "cubierto": true,
      "evidencia": "Endpoint DELETE /wishlist/remove/{product_id} devuelve 404 si el producto no estaba"
    },
    {
      "id": "SPEC-03",
      "cubierto": true,
      "evidencia": "GET /wishlist devuelve {items: [{product_id, name, saved_price, current_price, added_at}]} ordenado por added_at asc"
    },
    {
      "id": "SPEC-04",
      "cubierto": true,
      "evidencia": "Price Detection Scheduler compara precio actual con precio guardado usando umbral configurado"
    },
    {
      "id": "SPEC-05",
      "cubierto": true,
      "evidencia": "Email Notification Wrapper garantiza no más de un aviso por cliente‑producto cada 24 h y envía vía POST /internal/mail/send"
    },
    {
      "id": "SPEC-06",
      "cubierto": true,
      "evidencia": "Endpoint GET /wishlist/status devuelve {enabled: false, message: 'Inicia sesión…'} para invitados"
    }
  ],
  "funcionalidades_inventadas": [],
  "datos_inventados": [],
  "contratos_completos": true,
  "puntaje_revision": 7,
  "justificacion": "El diseño satisface todas las restricciones y la totalidad de la especificación. Se observan mejoras mínimas en la integración de precios actuales en las listas, por lo que se requiere ajustes menores."
}

{
  "restricciones": [
    {
      "id": "R1",
      "cumple": true,
      "evidencia": "Se adopta un monolito modular con arquitectura en capas porque la tienda ya está construida como una única aplicación FastAPI (R1)."
    },
    {
      "id": "R2",
      "cumple": true,
      "evidencia": "La base de datos PostgreSQL existente es la única base de datos; todos los componentes que persisten datos usan únicamente esa base."
    },
    {
      "id": "R3",
      "cumple": true,
      "evidencia": "La comunicación es síncrona e in‑proceso; se evitan colas o brokers externos (R3)."
    },
    {
      "id": "R4",
      "cumple": true,
      "evidencia": "Los correos se envían exclusivamente mediante el endpoint interno POST /internal/mail/send (R4)."
    },
    {
      "id": "R5",
      "cumple": true,
      "evidencia": "La detección de bajas de precio se ejecuta como tarea programada cada hora dentro de la misma aplicación (R5)."
    },
    {
      "id": "R6",
      "cumple": true,
      "evidencia": "No se integran servicios de terceros nuevos; se reutilizan el catálogo, el correo interno y la configuración existentes (R6)."
    }
  ],
  "specs": [
    {
      "id": "SPEC-01",
      "cubierto": true,
      "evidencia": "Endpoint POST /wishlist/add valida duplicados y límite de 50, guarda precio vigente y devuelve mensajes apropiados."
    },
    {
      "id": "SPEC-02",
      "cubierto": true,
      "evidencia": "Endpoint DELETE /wishlist/remove/{product_id} elimina el producto y responde 404 si no estaba en la lista."
    },
    {
      "id": "SPEC-03",
      "cubierto": true,
      "evidencia": "GET /wishlist devuelve items ordenados por added_at asc con precio guardado y precio actual."
    },
    {
      "id": "SPEC-04",
      "cubierto": true,
      "evidencia": "Price Detection Scheduler ejecuta cada hora, obtiene precio actual, compara con precio guardado usando umbral configurable (default 10%)."
    },
    {
      "id": "SPEC-05",
      "cubierto": true,
      "evidencia": "Email Notification Wrapper envía correo vía POST /internal/mail/send y asegura máximo un aviso por cliente‑producto cada 24 h mediante tabla de registro."
    },
    {
      "id": "SPEC-06",
      "cubierto": true,
      "evidencia": "GET /wishlist/status para invitados retorna enabled:false y mensaje \"Inicia sesión para usar tu lista de deseos\"."
    }
  ],
  "funcionalidades_inventadas": [],
  "datos_inventados": [],
  "contratos_completos": false,
  "puntaje_revision": 7,
  "justificacion": "Cubre todos los specs y respeta todas las restricciones, pero algunos contratos (ej. wrapper de correo y servicio de precio) no especifican explícitamente los códigos de error de salida."

}
